/td><td><?=number_format((int)$ci['system_quantity'])?></td><td><input class="counted-qty" data-sku="<?=e((string)($ci['sku']??''))?>" data-barcode="<?=e((string)($ci['barcode']??''))?>" type="number" min="0" step="1" name="counted[<?=(int)$ci['id']?>]" value="<?= $ci['counted_quantity']===null?'':(int)$ci['counted_quantity']?>"></td><td><label class="muted" style="font-size:10px"><input type="checkbox" name="recounted[<?=(int)$ci['id']?>]" value="1"> Recounted</label></td><td class="count-variance"><?= $ci['variance']===null?'—':number_format((int)$ci['variance'])?></td></tr><?php endforeach;?></tbody></table><p><button class="lc-btn">Save physical counts</button></p></form><?php if($canStockApprove):?><form method="post" class="lc-form" onsubmit="return confirm('Approve this count and post all entered variances to stock?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tab" value="stocktaking"><input type="hidden" name="action" value="approve_count"><input type="hidden" name="count_id" value="<?=$activeCount?>"><button class="lc-btn">Approve & post variances</button></form><form method="post" onsubmit="return confirm('Cancel this count? No stock changes will be posted.')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tab" value="stocktaking"><input type="hidden" name="action" value="cancel_count"><input type="hidden" name="count_id" value="<?=$activeCount?>"><button class="lc-btn secondary">Cancel count</button></form><?php endif;?></section><?php endif;?>
<section class="lc-panel"><h2>Stock count register</h2><p class="muted">Open a count report to review the original system quantities, physical counts and variances. Approved counts have already posted adjustments to the stock ledger.</p><table class="lc-table"><thead><tr><th>Count</th><th>Title</th><th>Date</th><th>Created by</th><th>Status</th><th>Report</th></tr></thead><tbody><?php foreach($counts as $c):?><tr><td><?=e($c['count_number'])?></td><td><?=e($c['title'])?></td><td><?=e($c['count_date'])?></td><td><?=e($c['full_name']??'—')?></td><td><?=e($c['status'])?></td><td><a href="stock_count_report.php?id=<?=(int)$c['id']?>" target="_blank" rel="noopener">View / Print</a></td></tr><?php endforeach;?></tbody></table></section>
<?php endif;?>
