<?php if($tab==='etims'&&$canEtims):?>
<section class="lc-panel"><h2>eTIMS invoice queue</h2><p class="muted">Environment: <strong><?=e(strtoupper($etimsEnvironment))?></strong> · Live KRA sender: <strong>Not implemented / disabled</strong> · Configuration flag: <?= $etimsEnabled==='1'?'enabled':'disabled' ?></p><p class="muted">Prepare completed POS invoices for the KRA integration. The prepared snapshot is internal normalized data, not a KRA-formatted request, and queueing does not submit to KRA.</p><?php if($canEtimsCreate):?><form method="post" class="lc-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tab" value="etims"><input type="hidden" name="action" value="queue_etims"><label>Completed invoice<select name="sale_id" required><option value="">Choose invoice</option><?php foreach($unqueuedSales as $sale):?><option value="<?=(int)$sale['id']?>"><?=e($sale['invoice_number'].' · KES '.number_format((float)$sale['total_amount'],2).' · '.$sale['sale_date'])?></option><?php endforeach;?></select></label><button class="lc-btn" <?=!$unqueuedSales?'disabled':''?>>Prepare invoice</button></form><?php endif;?><table class="lc-table"><thead><tr><th>Invoice</th><th>Sale ID</th><th>Amount</th><th>Status</th><th>KRA invoice</th><th>Queued</th></tr></thead><tbody><?php foreach($etims as $d):?><tr><td><?=e($d['invoice_number'])?></td><td><?=number_format((int)$d['sale_id'])?></td><td>KES <?=number_format((float)$d['total_amount'],2)?></td><td><?=e($d['status'])?></td><td><?=e($d['kra_invoice_number']??'—')?></td><td><?=e($d['created_at'])?><details><summary>Prepared data</summary><pre style="white-space:pre-wrap;max-width:520px;font-size:10px"><?=e($d['request_payload']??'No snapshot stored')?></pre></details></td></tr><?php endforeach;?></tbody></table><p class="muted">Live eTIMS transmission, signing, QR code and KRA response handling are not active in this build.</p></section>
<?php endif;?>
<script>
(function(){
 const search=document.getElementById('stockCountSearch');
 if(search){search.addEventListener('input',function(){const term=this.value.trim().toLowerCase();document.querySelectorAll('.stock-count-row').forEach(row=>{row.hidden=term!==''&&!row.dataset.search.includes(term);});});}
 document.querySelectorAll('.counted-qty').forEach(field=>{field.addEventListener('input',function(){const row=this.closest('tr');const systemCell=row?row.children[3]:null;const varianceCell=row?row.querySelector('.count-variance'):null;if(!systemCell||!varianceCell)return;if(this.value===''){varianceCell.textContent='—';return;}const variance=parseInt(this.value,10)-parseInt(systemCell.textContent.replace(/,/g,''),10);varianceCell.textContent=variance>0?'+'+variance.toLocaleString():variance.toLocaleString();});});
 const scanner=document.getElementById('stockCountScanner');
 if(!scanner)return;
 scanner.addEventListener('keydown',function(event){
  if(event.key!=='Enter')return;
  event.preventDefault();
  const code=scanner.value.trim().toLowerCase();
  if(!code)return;
  const fields=Array.from(document.querySelectorAll('.counted-qty'));
  const matches=fields.filter(field=>(field.dataset.sku||'').trim().toLowerCase()===code||(field.dataset.barcode||'').trim().toLowerCase()===code);
  if(matches.length!==1){alert(matches.length?'More than one product matches this SKU/barcode. Check the product records.':'No product in this count matches SKU/barcode: '+scanner.value.trim());scanner.select();return;}
  const match=matches[0];
  match.value=String((parseInt(match.value||'0',10)||0)+1);
  const recountBox=match.closest('tr')?.querySelector('input[type="checkbox"][name^="recounted"]');if(recountBox)recountBox.checked=true;
  const row=match.closest('tr');
  const systemCell=row?row.children[3]:null;
  const varianceCell=row?row.querySelector('.count-variance'):null;
  if(systemCell&&varianceCell){const variance=parseInt(match.value,10)-parseInt(systemCell.textContent.replace(/,/g,''),10);varianceCell.textContent=variance>0?'+'+variance.toLocaleString():variance.toLocaleString();}
  match.dispatchEvent(new Event('change',{bubbles:true}));
  scanner.value='';scanner.focus();
 });
})();
</script>
</main>
